"""Helpers for retrieving prices from the internal pricing service."""

import json
import os
import urllib.request
from collections.abc import Iterable

BASE = os.environ.get(
    "PRICES_BASE_URL", "http://prices.internal/api/v1/price"
).rstrip("/")


def get_price(sku: str) -> float:
    """Return the current price for *sku* from the pricing service."""
    request = urllib.request.Request(f"{BASE}/{sku}")
    if pricing_key := os.environ.get("PRICING_KEY"):
        request.add_header("X-Pricing-Key", pricing_key)

    with urllib.request.urlopen(request, timeout=5) as response:
        return float(json.load(response)["price"])


def get_total(skus: list[str]) -> float:
    """Return the sum of the current service prices for *skus*."""
    return sum(map(get_price, skus), 0.0)
